import{_ as s,a0 as l,w as a,s as p,ao as u,I as i,x as r,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"OWL 項目：物聯網正嘗試在災難中讓一切保持聯絡 | LCTT x X-CMD","titleTemplate":false,"description":"OWL 項目：物聯網正嘗試在災難中讓一切保持聯絡 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"OWL 項目：物聯網正嘗試在災難中讓一切保持聯絡 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"OWL 項目：物聯網正嘗試在災難中讓一切保持聯絡 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200706 Project OWL- IoT trying to hold connectivity together in disasters","title":"OWL 項目：物聯網正嘗試在災難中讓一切保持聯絡","tag":"202007","desc":""},"relativePath":"202007/20200706 Project OWL- IoT trying to hold connectivity together in disasters.md","filePath":"[post].md"}'),d={name:"202007/20200706 Project OWL- IoT trying to hold connectivity together in disasters.md"};function m(y,t,f,w,L,T){const o=l("Link");return a(),p("div",null,[t[15]||(t[15]=u('<h1 id="owl-項目-物聯網正嘗試在災難中讓一切保持聯絡" tabindex="-1">OWL 項目：物聯網正嘗試在災難中讓一切保持聯絡 <a class="header-anchor" href="#owl-項目-物聯網正嘗試在災難中讓一切保持聯絡" aria-label="Permalink to “OWL 項目：物聯網正嘗試在災難中讓一切保持聯絡”">​</a></h1><blockquote><p>當自然災害破壞了傳統的通信連接時，配置在<ruby>多跳網絡<rt>mesh network</rt></ruby>的物聯網設備可以迅速部署以提供基本的連接。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202007/21/135614mwr8rxr6lw5xefjs.jpg" alt=""></p><p>OWL 項目負責人在最近的開源峯會上説，一個以多跳網絡、物聯網和 LoRa 連接為中心的開源項目可以幫助急救和受災人員在自然災害之後保持聯繫。</p><p>OWL 項目的應用場景是當在自然災害之後頻繁發生的通信中斷時。無論是蜂窩網絡還是有線網絡，大範圍的中斷會頻繁阻礙急救服務、供應和在暴風雨或其他重大災難後必須解決關鍵問題的信息流。</p><p>該項目通過一大羣“<ruby>鴨子<rt>duck</rt></ruby>”（便宜、易於部署且不需要現有基礎設施支持的小型無線模組）實現這個目的。一些“鴨子”是太陽能的，其它一些則用的是耐用電池。每隻“鴨子”配備一個 LoRa 無線電，用於在網絡上和其它“鴨子”進行通信，同時還配備有 Wi-Fi，而且可能配備藍牙和 GPS 來實現其他功能。</p><p>這個想法是這樣的，當網絡癱瘓時，用户可以使用他們的智能手機或者筆記本電腦與“鴨子”建立一個 Wi-Fi 連接，這個“鴨子”可以將小塊的信息傳遞到網絡的其他部分。信息向網絡後端傳遞，直到到達“<ruby>鴨子爸爸<rt>papaduck</rt></ruby>”，“鴨子爸爸”裝備了可以與雲上的 OWL 數據管理系統連接的衞星系統（OWL 代表 ”<ruby>組織<rt>organization</rt></ruby>、<ruby>位置<rt>whereabouts</rt></ruby>和<ruby>物流<rt>logistics</rt></ruby>”）。信息可以通過雲在智能手機或者網頁上進行可視化，甚至可以通過 API 插入到現有的系統中。</p><p>秘密在於“<ruby>鴨羣<rt>ClusterDuck</rt></ruby>” 協議，這是一個開源固件，即使在一些模組不能正常工作的網絡中，它仍然能保持信息流通。它就是設計用來工作在大量便宜且容易獲取的計算硬件上，類似樹莓派的硬件，這樣可以更容易且更快捷的建立一個“鴨羣”網絡。</p><p>創始人 Bryan Knouse 表示，這個項目的創建，是因為在 2017 年和 2018 年的毀滅性颶風中，要與受影響社區進行有效的通信而採取救援措施，面臨着巨大的困難。</p><p>“我們的一些創始成員經歷了這些災難，然後我們會問‘我們該做些什麼？’”，他説道。</p><p>在馬亞圭斯，該項目有一批來自波多黎各大學的學生和教授，大多數的系統測試都在那裏進行。Knouse 説，校園中目前有 17 個太陽能“鴨子”，分佈在屋頂和樹上，並且計劃增加數量。</p><p>他説，“這種關係實際上創建了一個開源社區，這些學生和教授正在幫助我們開發這個項目。”</p><hr>',13)),i("p",null,[t[1]||(t[1]=r("via: ",-1)),e(o,{href:"https://www.networkworld.com/article/3564980/project-owl-iot-trying-to-hold-connectivity-together-in-disasters.html"},{default:n(()=>[...t[0]||(t[0]=[r("https://www.networkworld.com/article/3564980/project-owl-iot-trying-to-hold-connectivity-together-in-disasters.html",-1)])]),_:1})]),i("p",null,[t[6]||(t[6]=r("作者：",-1)),e(o,{href:"https://www.networkworld.com/author/Jon-Gold/"},{default:n(()=>[...t[2]||(t[2]=[r("Jon Gold",-1)])]),_:1}),t[7]||(t[7]=r(" 選題：",-1)),e(o,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[3]||(t[3]=[r("lujun9972",-1)])]),_:1}),t[8]||(t[8]=r(" 譯者：",-1)),e(o,{href:"https://github.com/Yufei-Yan"},{default:n(()=>[...t[4]||(t[4]=[r("Yufei-Yan",-1)])]),_:1}),t[9]||(t[9]=r(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[r("wxy",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=r("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[r("LCTT",-1)])]),_:1}),t[13]||(t[13]=r(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[r("Linux中國",-1)])]),_:1}),t[14]||(t[14]=r(" 榮譽推出",-1))])])}const x=s(d,[["render",m]]);export{h as __pageData,x as default};
